                <Tooltip title="Schedule">
                    <span>
                        <IconButton
                            aria-expanded={scheduleOpen}
                            aria-haspopup="dialog"
                            aria-label="Schedule"
                            disabled={!settings.backendAvailable}
                            onClick={handleToggleSchedule}
                            size="small"
                            sx={{ color: scheduled ? 'warning.main' : undefined }}
                        >
                            <CalendarOutline sx={{ fontSize: 18 }} />
                        </IconButton>
                    </span>
                </Tooltip>
            ) : null}
            {showStopControl ? (
                <Tooltip title="Stop">
                    <span>
                        <IconButton
                            aria-label="Stop"
                            disabled={browsingHistory || !settings.backendAvailable}
                            onClick={handleCancel}
                            size="small"
                        >
                            <StopOutlined sx={{ fontSize: 18 }} />
                        </IconButton>
                    </span>
                </Tooltip>
            ) : null}
            {showAgentSend ? (
                <Tooltip title="Send. Ctrl+Enter.">
                    <span>
                        <IconButton
                            aria-label="Send"
                            color="primary"
                            disabled={runDisabled}
                            onClick={handlePrimaryRun}
                            ref={primaryButtonRef}
                            size="small"
                        >
                            <ArrowUpwardOutlined sx={{ fontSize: 18 }} />
                        </IconButton>
                    </span>
                </Tooltip>
            ) : showCommandRun ? (
                <Tooltip title="Run">
                    <Button
                        disabled={runDisabled}
                        onClick={handlePrimaryRun}
                        ref={primaryButtonRef}
                        size="small"
                        startIcon={<Play sx={{ fontSize: '13px !important' }} />}
                        sx={{ height: 34, px: 2 }}
                        variant="contained"
                    >
                        Run
                    </Button>
                </Tooltip>
            ) : null}
        </Box>
    );
}
